Dataspatium.assets.register("presets/api/brreg-enhetsregisteret.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"brreg-enhetsregisteret\",\n  \"name\": \"Enhetsregisteret (Brønnøysundregistrene)\",\n  \"publisher\": \"Brønnøysundregistrene\",\n  \"description\": \"Norges register över företag, föreningar och offentliga organ: namn, organisationsnummer, organisationsform, adress, näringsgren, antal anställda och registreringsdatum. Sök på namn, kommun, organisationsform eller näringsgrenskod; högst 10 000 träffar per sökning.\",\n  \"docs\": \"https://data.brreg.no/enhetsregisteret/api/dokumentasjon/no/index.html\",\n  \"license\": { \"name\": \"NLOD 2.0 (Norsk lisens for offentlige data)\", \"url\": \"https://data.norge.no/nlod/no/2.0\" },\n  \"level\": 1,\n  \"country\": \"NO\",\n  \"baseUrl\": \"https://data.brreg.no/enhetsregisteret/api\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 5, \"perSeconds\": 1 },\n  \"endpoints\": [\n    {\n      \"id\": \"enheter\",\n      \"name\": \"Sök enheter\",\n      \"description\": \"Företag och organisationer som matchar sökvillkoren. Minst ett villkor behövs.\",\n      \"method\": \"GET\",\n      \"path\": \"/enheter\",\n      \"params\": [\n        { \"name\": \"navn\", \"in\": \"query\", \"label\": \"Namn (del av)\", \"type\": \"string\", \"example\": \"Statistisk sentralbyrå\" },\n        { \"name\": \"kommunenummer\", \"in\": \"query\", \"label\": \"Kommunnummer\", \"type\": \"string\", \"example\": \"0301\" },\n        { \"name\": \"organisasjonsform\", \"in\": \"query\", \"label\": \"Organisationsform (kod)\", \"type\": \"string\", \"example\": \"AS\", \"help\": \"Till exempel AS, ENK, ANS, KOMM, STAT eller FLI.\" },\n        { \"name\": \"naeringskode\", \"in\": \"query\", \"label\": \"Näringsgrenskod (NACE)\", \"type\": \"string\", \"example\": \"84.110\" },\n        { \"name\": \"size\", \"in\": \"query\", \"type\": \"number\", \"default\": 100, \"hidden\": true }\n      ],\n      \"pagination\": { \"type\": \"page\", \"param\": \"page\", \"start\": 0, \"sizeParam\": \"size\", \"size\": 100, \"totalPagesPath\": \"page.totalPages\", \"maxPages\": 20 },\n      \"response\": { \"format\": \"json\", \"path\": \"_embedded.enheter\", \"drop\": [\"_links\", \"links\"] },\n      \"dataset\": { \"name\": \"Enhetsregisteret: {navn} {kommunenummer} {organisasjonsform}\", \"keys\": [\"organisasjonsnummer\"] }\n    },\n    {\n      \"id\": \"kommuner\",\n      \"name\": \"Kommuner\",\n      \"description\": \"Norges kommuner med kommunnummer och namn.\",\n      \"method\": \"GET\",\n      \"path\": \"/kommuner\",\n      \"params\": [\n        { \"name\": \"size\", \"in\": \"query\", \"type\": \"number\", \"default\": 500, \"hidden\": true }\n      ],\n      \"pagination\": { \"type\": \"page\", \"param\": \"page\", \"start\": 0, \"sizeParam\": \"size\", \"size\": 500, \"totalPagesPath\": \"page.totalPages\", \"maxPages\": 3 },\n      \"response\": { \"format\": \"json\", \"path\": \"_embedded.kommuner\", \"drop\": [\"_links\"] },\n      \"dataset\": { \"name\": \"Norska kommuner (Enhetsregisteret)\" }\n    }\n  ],\n  \"i18n\": {\n    \"en\": { \"name\": \"Central Coordinating Register for Legal Entities (Brønnøysund)\", \"publisher\": \"Brønnøysund Register Centre\", \"description\": \"Norway's register of companies, associations and public bodies: name, organisation number, organisation form, address, industry, number of employees and registration date. Search by name, municipality, organisation form or industry code; at most 10,000 hits per search.\", \"endpoints\": { \"enheter\": { \"name\": \"Search entities\", \"description\": \"Companies and organisations matching the criteria. At least one criterion is needed.\", \"params\": { \"navn\": { \"label\": \"Name (part of)\" }, \"kommunenummer\": { \"label\": \"Municipality number\" }, \"organisasjonsform\": { \"label\": \"Organisation form (code)\", \"help\": \"For example AS, ENK, ANS, KOMM, STAT or FLI.\" }, \"naeringskode\": { \"label\": \"Industry code (NACE)\" } } }, \"kommuner\": { \"name\": \"Municipalities\", \"description\": \"Norway's municipalities with number and name.\" } }, \"dataset\": { \"kommuner\": \"Norwegian municipalities (Enhetsregisteret)\" } },\n    \"da\": { \"name\": \"Enhetsregisteret (Brønnøysundregistrene)\", \"publisher\": \"Brønnøysundregistrene\", \"description\": \"Norges register over virksomheder, foreninger og offentlige organer: navn, organisationsnummer, organisationsform, adresse, branche, antal ansatte og registreringsdato. Søg på navn, kommune, organisationsform eller branchekode; højst 10 000 træffere pr. søgning.\", \"endpoints\": { \"enheter\": { \"name\": \"Søg enheder\", \"description\": \"Virksomheder og organisationer, der matcher søgekriterierne. Mindst ét kriterium kræves.\", \"params\": { \"navn\": { \"label\": \"Navn (del af)\" }, \"kommunenummer\": { \"label\": \"Kommunenummer\" }, \"organisasjonsform\": { \"label\": \"Organisationsform (kode)\", \"help\": \"For eksempel AS, ENK, ANS, KOMM, STAT eller FLI.\" }, \"naeringskode\": { \"label\": \"Branchekode (NACE)\" } } }, \"kommuner\": { \"name\": \"Kommuner\", \"description\": \"Norges kommuner med kommunenummer og navn.\" } }, \"dataset\": { \"kommuner\": \"Norske kommuner (Enhetsregisteret)\" } },\n    \"nb\": { \"name\": \"Enhetsregisteret (Brønnøysundregistrene)\", \"publisher\": \"Brønnøysundregistrene\", \"description\": \"Norges register over foretak, foreninger og offentlige organer: navn, organisasjonsnummer, organisasjonsform, adresse, næringskode, antall ansatte og registreringsdato. Søk på navn, kommune, organisasjonsform eller næringskode; høyst 10 000 treff per søk.\", \"endpoints\": { \"enheter\": { \"name\": \"Søk enheter\", \"description\": \"Foretak og organisasjoner som matcher søkekriteriene. Minst ett kriterium trengs.\", \"params\": { \"navn\": { \"label\": \"Navn (del av)\" }, \"kommunenummer\": { \"label\": \"Kommunenummer\" }, \"organisasjonsform\": { \"label\": \"Organisasjonsform (kode)\", \"help\": \"For eksempel AS, ENK, ANS, KOMM, STAT eller FLI.\" }, \"naeringskode\": { \"label\": \"Næringskode (NACE)\" } } }, \"kommuner\": { \"name\": \"Kommuner\", \"description\": \"Norges kommuner med kommunenummer og navn.\" } }, \"dataset\": { \"kommuner\": \"Norske kommuner (Enhetsregisteret)\" } },\n    \"fi\": { \"name\": \"Enhetsregisteret (Norjan yritysrekisteri)\", \"publisher\": \"Brønnøysundregistrene\", \"description\": \"Norjan yritysten, yhdistysten ja julkisten toimijoiden rekisteri: nimi, organisaationumero, yhtiömuoto, osoite, toimiala, työntekijämäärä ja rekisteröintipäivä. Hae nimellä, kunnalla, yhtiömuodolla tai toimialakoodilla; enintään 10 000 osumaa per haku.\", \"endpoints\": { \"enheter\": { \"name\": \"Hae yksiköitä\", \"description\": \"Hakuehtoja vastaavat yritykset ja organisaatiot. Vähintään yksi ehto tarvitaan.\", \"params\": { \"navn\": { \"label\": \"Nimi (osa)\" }, \"kommunenummer\": { \"label\": \"Kuntanumero\" }, \"organisasjonsform\": { \"label\": \"Yhtiömuoto (koodi)\", \"help\": \"Esimerkiksi AS, ENK, ANS, KOMM, STAT tai FLI.\" }, \"naeringskode\": { \"label\": \"Toimialakoodi (NACE)\" } } }, \"kommuner\": { \"name\": \"Kunnat\", \"description\": \"Norjan kunnat numeroineen ja nimineen.\" } }, \"dataset\": { \"kommuner\": \"Norjan kunnat (Enhetsregisteret)\" } },\n    \"is\": { \"name\": \"Enhetsregisteret (fyrirtækjaskrá Noregs)\", \"publisher\": \"Brønnøysundregistrene\", \"description\": \"Skrá Noregs yfir fyrirtæki, félög og opinbera aðila: heiti, fyrirtækjanúmer, rekstrarform, heimilisfang, atvinnugrein, fjöldi starfsmanna og skráningardagur. Leitaðu eftir heiti, sveitarfélagi, rekstrarformi eða atvinnugreinakóða; að hámarki 10 000 niðurstöður í hverri leit.\", \"endpoints\": { \"enheter\": { \"name\": \"Leita að einingum\", \"description\": \"Fyrirtæki og samtök sem passa við leitarskilyrðin. Minnst eitt skilyrði þarf.\", \"params\": { \"navn\": { \"label\": \"Heiti (hluti af)\" }, \"kommunenummer\": { \"label\": \"Sveitarfélagsnúmer\" }, \"organisasjonsform\": { \"label\": \"Rekstrarform (kóði)\", \"help\": \"Til dæmis AS, ENK, ANS, KOMM, STAT eða FLI.\" }, \"naeringskode\": { \"label\": \"Atvinnugreinakóði (NACE)\" } } }, \"kommuner\": { \"name\": \"Sveitarfélög\", \"description\": \"Sveitarfélög Noregs með númeri og heiti.\" } }, \"dataset\": { \"kommuner\": \"Norsk sveitarfélög (Enhetsregisteret)\" } }\n  }\n}\n");
